@Component("matter-handler")
@ProcessingGroup("matter-processing-group")
public class MatterEventHandler {
	
	// core constructor
	MatterEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateMatterEvent
     */
    @EventHandler
    public void handle( CreateMatterEvent event) {
        entityManager.persist(new Matter(event.getMatterId(), event.getMatterName(), event.getLeadCounsel(), event.getLegalHolds(), event.getOrganization(), event.getDataBreaches(), event.getContracts(), event.getMatterType(), event.getStatus()));
    }

    /*
     * @param	event UpdateMatterEvent
     */
    @EventHandler
    public Matter handle( UpdateMatterEvent event) {
    	entityManager.merge(new Matter(event.getMatterId(), event.getMatterName(), event.getLeadCounsel(), event.getLegalHolds(), event.getOrganization(), event.getDataBreaches(), event.getContracts(), event.getMatterType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteMatterEvent
     */
    @EventHandler
    public void on( DeleteMatterEvent event) {
    	Matter entity = new Matter();
   
    	// ------------------------------------------
    	// apply the MatterId
    	// ------------------------------------------
    	entity.setMatterId( event.getMatterId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final MatterRepository matterEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(MatterEventHandler.class.getName());

}
